style.css:
@-moz-document url-prefix("https://voice.google.com/") {
#gv-root {
    background-color: #111 !important;
    color: #fff;
}

#gv-root div {
    --mat-sys-background: #111;
    border-color: #000 !important;
    border-width: 1px;
}

#gb {
    background-color: #000 !important;
}

gv-thread-details {
    background-color: #222 !important;
}

gv-mei-banner div {
    background-color: #111 !important;
    color: #777;
}

mat-card,
.mat-mdc-card {
    background-color: #222 !important;
}

header,
#gb {
    background-color: #222 !important;
}

.outgoing div.bubble {
    background-color: #1a1a1a !important;
    color: #808080 !important;
}

div.bubble {
    background-color: #393939 !important;
    color: #9f9f9f !important;
}

.greeting {
    color: #FFF;
}

.status {
    color: #AAA;
}

mat-drawer-content div.header {
    background-color: #111 !important;
}

.upgrade-link {
    display: none;
}

.learn-more-button {
