}

.calling-view {
    background-color: #111 !important;
}
.action-buttons {
    background-color: #1a1a1a !important;
}

.threads-header {
    background-color: #111 !important;
}

.threads-button div {
    color: #c1c1c1;
}

.header {
    background-color: #353535 !important;
    color: #CCC !important;
}

.time-container div {
    color: #CCC;
}
.mdc-button {
    background-color: #fff;
}
.transcription-text {
    color: #CCC !important;
}

.header-content h2 {
    color: #CCC !important;
}

.internalHeader {
    color: #CCC !important;
}

.internalSubheader {
    color: #717171 !important;
}

.content-container gv-side-nav {
    background-color: #111
}

.deviceLabel {
    color: #FFF !important;
}

.sectionTitle {
    color: #999 !important;
}

.deviceDetails {
    color: #868585 !important;
}

