}

.threads {
    background-color: #222 !important;
}

.primary-text,
.header-title {
    color: #CCC !important;
}

.nav-item-label {
    color: #b5b2b2 !important;
}
.sZ3gbf {
    background-color: #222 !important;
}

.navItemLabel {
    color: #bbb;
}

.cdk-visually-hidden {
    color: #CCC !important;
}

.subheader {
    color: #8a8a8a !important;
}

.inbox-summary-container {
    background-color: #111 !important;
}

.label {
