    background-color: #999 !important;
    color: #333!important;
}

.gb_Me div {
    background-color: #222 !important;
    color: #BBB !important;
}

.root .container {
    background-color: #222 !important;
    color: #BBB !important;
}

.message-input-container textarea {
    background-color: #222 !important;
